    case 7:
      str = "\\a"
      return true
    case 8:
      str = "\\b"
      return true
    case 12:
      str = "\\f"
      return true
    case 10:
      str = "\\n"
      return true
    case 13:
      str = "\\r"
      return true
    case 9:
      str = "\\t"
