        _ = "".withCString { empty in
          withVaList([Int32(pad), empty, Int32(bitPattern: UInt32(wc))]) { vprintf("%*s%C", $0) }
        }
        pr.mbleft = clen - 1
      }
      return false
    } else {
      str = "%03o".cFormat(pp)
      return true
    }
  }
  
  func conv_u(pr: inout PR, bp p: UInt8) {
    let list = ["nul", "soh", "stx", "etx", "eot", "enq", "ack", "bel",
